<?php if(post_password_required()) return; ?><section id="comments" class="comments-area mt-5"><?php if(have_comments()): ?><h2 class="h4 mb-4"><?php comments_number(__('No comments','bootstrap-mega-starter'),__('One comment','bootstrap-mega-starter'),__('% comments','bootstrap-mega-starter')); ?></h2><ol class="comment-list list-unstyled"><?php wp_list_comments(['style'=>'ol','short_ping'=>true]); ?></ol><?php the_comments_navigation(); endif; ?><?php if(!comments_open()&&get_comments_number()): ?><p><?php esc_html_e('Comments are closed.','bootstrap-mega-starter'); ?></p><?php endif; ?><?php comment_form(); ?></section>
